text:
{
  "title": "نموذج طلب توظيف وإقرار معالجة البيانات الشخصية - شركة الأفق الرقمي المحدودة",
  "planted": [
    {
      "slot": "p1",
      "text": "يُعد إرسال نموذج التوظيف هذا استهلالاً للمسار المهني، وتعتبر تعبئة الحقول وتقديم الطلب موافقة ضمنية ومبدئية من المتقدم على استخدام بياناته في كافة الأغراض التشغيلية للشركة، ولا تقبل طلبات سحب الموافقة أو تقييد معالجة الملف بعد إرساله نهائياً نظراً لارتباطه بالدورات المستندية الداخلية."
    },
    {
      "slot": "p2",
      "text": "تتم إزالة كافة مستندات المرتمشين وغير المقبولين وطلبjاتهم من قواعد البيانات النشطة فور اكتمال شغور الوظيفة المتقدم لها وعدم الحاجة إليها مجدداً، ما لم تقضِ المتطلبات التنظيمية للعمل أو التدقيق المالي الاحتفاظ ببعض السجلات لفترة محددة."
    },
    {
      "slot": "p3",
      "text": "يحق للمتقدم في أي وقت مراجعة بياناته المقدمة، وطلب تصحيح أو استكمال أي معلومات غير دقيقة، فضلاً عن طلب إتلاف الملف بالكامل في حال قرر العدول عن التقدم للوظيفة."
    },
    {
      "slot": "p4",
      "text": "تلتزم الشركة بجمع القدر المناسب والملائم من المعلومات الشخصية والمهنية للمتقدمين بما يخدم تقييم الكفاءة والملائمة لشغل الوظائف المتاحة بدقة."
    }
  ],
  "neutral": [
    "تخضع كافة النزاعات الناشئة عن تفسير أو تنفيذ هذا النموذج للقوانين والأنظمة المعمول بها في المملكة العربية السعودية.",
    "تُعرّف الشركة في هذا المستند بأنها شركة الأفق الرقمي المحدودة، ويُقصد بالمتقدم كل شخص طبيعي يتقدم بطلب لشغل وظيفة شاغرة لديها.",
    "لا تتحمل الشركة أي مسؤولية قانونية عن أي خسائر غير مباشرة أو تبعية قدל تنتج عن تعطل الخدمات الإلكترونية لتقديم الطلبات لأسباب تقنية خارجة عن إرادتها.",
    "تُعد كافة الحقوق الفكرية والتصاميم والنصوص الواردة في هذا النموذج ملكية خالصة للشركة، ولا يحق لأي جهة إعادة نشرها أو استغلالها دون إذن مسبق.",
    "تتم كافة المراسلات الرسمية والإشعارات المتبادلة بين الطرفين عبر البريد الإلكتروني المدون في نموذج الطلب، وتعتبر منتجة لآثارها القانونية بمجرد إرسالها.",
    "لا يترتب على تقديم هذا النموذج أي التزام مالي أو رسوم تجاه المتقدم، وتتحمل الشركة وحدها تكاليف عمليات الفرز والتقييم والتوظيف."
  ]
}
